from pathlib import Path
from html import escape

def tx(es,en,tag='span',cls=''):
 return f'<{tag}'+(f' class="{cls}"' if cls else '')+f' data-es="{escape(es,quote=True)}" data-en="{escape(en,quote=True)}">{es}</{tag}>'
def arrow():return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>'
def link(es,en,href,cls='text-link'):
 return f'<a class="{cls}" href="{href}">{tx(es,en)}{arrow()}</a>'
